export function getLocalizedQueueStepDesc(
  stepId: 'checked_in' | 'in_queue' | 'at_counter' | 'procured',
  lang: Language
): string {
  const step = QUEUE_STEP_DESCS[stepId]
  if (!step) return ''
  return step[lang] || step['en'] || ''
}

