    ta: 'தற்போது செயலில் உள்ள முன்பதிவு இல்லை. ஸ்லாட் முன்பதிவு செய்தவுடன் நேரலை டோக்கன் இங்கு தோன்றும்.',
    kn: 'ನಿಮ್ಮ ಖಾತೆಯಲ್ಲಿ ಸಕ್ರಿಯ ಸ್ಲಾಟ್ ಬುಕಿಂಗ್ ಇಲ್ಲ. ಸ್ಲಾಟ್ ಬುಕ್ ಮಾಡಿದ ನಂತರ ಲೈವ್ ಟೋಕನ್ ಇಲ್ಲಿ ಕಾಣಿಸುತ್ತದೆ.',
    ml: 'നിലവിൽ സജീവമായ സ്ലോട്ട് ബുക്കിംഗ് ഇല്ല. സ്ലോട്ട് ബുക്ക് ചെയ്തുകഴിഞ്ഞാൽ ലൈവ് ടോക്കൺ ഇവിടെ കാണാം.',
