    te: 'నేరుగా లాగిన్ కావడానికి పేరు మరియు మొబైల్ నంబర్ నమోదు చేయండి (OTP అవసరం లేదు)',
    ta: 'நேரடி உள்நுழைவுக்கு பெயர் மற்றும் மொபைல் எண்ணை உள்ளிடவும் (OTP தேவையில்லை)',
    kn: 'ನೇರ ಪ್ರವೇಶಕ್ಕಾಗಿ ಹೆಸರು ಮತ್ತು ಮೊಬೈಲ್ ಸಂಖ್ಯೆಯನ್ನು ನಮೂದಿಸಿ (OTP ಅಗತ್ಯವಿಲ್ಲ)',
    ml: 'നേരിട്ട് പ്രവേശിക്കാൻ പേരും മൊബൈൽ നമ്പറും നൽകുക (OTP ആവശ്യമില്ല)',
    or: 'ସିଧାସଳଖ ଲଗଇନ୍ ପାଇଁ ନାମ ଏବଂ ମୋବାଇଲ୍ ନମ୍ବର ଦିଅନ୍ତୁ (OTP ଆବଶ୍ୟକ ନାହିଁ)',
    as: 'পোনপটীয়া প্ৰৱেশৰ বাবে নাম আৰু মোবাইল নম্বৰ দিয়ক (OTP প্ৰয়োজন নাই)',
