    bn: 'আপনি এখনও কোনো স্লট বুক করেননি। স্লট বুক করার পর এই ধাপগুলো সক্রিয় হবে।',
    te: 'మీరు ఇంకా ఎటువంటి స్లాట్ బుక్ చేయలేదు. స్లాట్ బుక్ చేసిన తర్వాత ఈ దశలు సక్రియం అవుతాయి.',
    ta: 'நீங்கள் இன்னும் ஸ்லாட் முன்பதிவு செய்யவில்லை. முன்பதிவு செய்த பின் இவை செயல்படும்.',
    kn: 'ನೀವು ಇನ್ನೂ ಯಾವುದೇ ಸ್ಲಾಟ್ ಬುಕ್ ಮಾಡಿಲ್ಲ. ಬುಕ್ ಮಾಡಿದ ನಂತರ ಈ ಹಂತಗಳು ಸಕ್ರಿಯಗೊಳ್ಳುತ್ತವೆ.',
    ml: 'നിങ്ങൾ ഇതുവരെ സ്ലോട്ട് ബുക്ക് ചെയ്തിട്ടില്ല. ബുക്ക് ചെയ്ത ശേഷം ഇത് സജീവമാകും.',
    or: 'ଆପଣ ଏପର୍ଯ୍ୟନ୍ତ କୌଣସି ସ୍ଲଟ୍ ବୁକ୍ କରିନାହାଁନ୍ତି ।',
    as: 'আপুনি এতিয়ালৈকে কোনো স্লট বুক কৰা নাই।',
    ur: 'آپ نے ابھی تک کوئی سلاٹ بک نہیں کیا۔',
