export function getLocalizedUIString(key: string, lang: Language): string {
  const item = COMMON_UI_TEXTS[key]
  if (!item) return key
  return item[lang] || item['en'] || key
}

export function getLocalizedBookingStatus(status: string, lang: Language): string {
  const map: Record<string, string> = {
    BOOKED: getLocalizedUIString('statusBooked', lang),
    IN_QUEUE: getLocalizedUIString('statusInQueue', lang),
    AT_COUNTER: getLocalizedUIString('statusAtCounter', lang),
    GRADED: getLocalizedUIString('statusGraded', lang),
    PROCURED: getLocalizedUIString('statusProcured', lang),
    COMPLETED: getLocalizedUIString('statusCompleted', lang),
    PAYMENT_INITIATED: getLocalizedUIString('statusPaymentInitiated', lang),
  }
  return map[status] || status.replace(/_/g, ' ')
}


